pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = norm_pr * norm_pr * 30.0 + norm_pr * 20.0;

    // Strong reward for near-perfect fill (2-step lookahead core).
    if post_residual == 0 {
        score -= 1000.0;
    } else if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 800.0;
            if fitting_bins_count > 1 {
                score -= 6.0;
            }
        } else {
            // Quadratic penalty on mismatch relative to capacity.
            score += (diff / cap) * (diff / cap) * 60.0;
            // One-sided gap: only excess residual hurts next-item fitting.
            let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64 / cap;
            score += gap * gap * 10.0;
            // Joint fit: next item fits and bin was already usable — reward compaction.
            if post_residual >= next_item_size && bin_residual >= item_size {
                let joint = (post_residual - next_item_size) as f64 / cap;
                score -= (1.0 - joint) * 7.0;
            }
            // Near-miss sliver: post-residual barely fits next item while other
            // bins could also take it — mild penalty to preserve flexibility.
            if post_residual >= next_item_size && post_residual < next_item_size * 2 && fitting_bins_count > 1 {
                score += 2.5 * norm_pr;
            }
            // Next item won't fit here: penalize tight bins less when residual is large.
            if next_item_size as f64 > pr && norm_pr > 0.15 {
                score += norm_pr * 6.0;
            }
            if post_residual < next_item_size && post_residual > 0 {
                score += 5.5 * (1.0 - norm_pr);
            }
            // Refined dead-end metric: residual after hosting next item is only
            // useful if it can host at least a small item; weight by fleet slack.
            if post_residual >= next_item_size {
                let after = (post_residual - next_item_size) as f64 / cap;
                if after > 0.0 && after * cap < item_size as f64 {
                    score += 3.0 * (1.0 - norm_pr);
                }
                let fleet_slack = (mean_residual / cap).min(1.0);
                score += (1.0 - after) * (1.5 + 2.0 * (1.0 - fleet_slack));
            }
            // Keep bins whose post-residual covers average upcoming demand.
            if post_residual >= next_item_size {
                let avg_next = mean_residual / (open_bins_count.max(1) as f64);
                if next_item_size as f64 <= avg_next * 1.5 {
                    score -= 1.2 * norm_pr;
                }
            }
        }
    }

    // Penalize creating small unusable dead space (below typical min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }
    // Sliver relative to upcoming demand: dead space smaller than either current
    // or next item is nearly unusable — scale penalty with fullness.
    if post_residual > 0 && post_residual < item_size.max(next_item_size) {
        score += 12.0 * (1.0 - norm_pr);
    }
    // Reward near-perfect residuals that aren't exact zero.
    if post_residual > 0 && norm_pr < 0.02 {
        score -= 9.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: discourage opening a new bin unless current bin would
    // leave a lot of dead space relative to mean residual.
    if bin_residual == bin_capacity {
        let mut tight = 6.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            tight = 0.0;
        }
        if fitting_bins_count == 0 {
            tight -= 4.0;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            tight += 3.0;
        }
        if fitting_bins_count > 0 {
            tight += 2.0;
            if next_item_size > 0 {
                tight -= 1.5 / (fitting_bins_count as f64);
            }
        }
        if norm_pr < 0.05 {
            tight -= 1.0;
        }
        // Fleet nearly full: fresh bin is cheap.
        if mean_residual / cap < 0.03 && fitting_bins_count > 0 {
            tight -= 1.5;
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.9 && fitting_bins_count > 0 {
            tight += 2.0;
        }
        if fitting_bins_count == 1 && next_item_size > 0 && next_item_size > post_residual {
            tight -= 2.5;
        }
        // Several fitting bins but tiny residuals: fresh bin relatively cheaper.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64);
            if (avg_fit as u32) < item_size * 2 && progress < 0.85 {
                tight -= 1.0;
            }
        }
        // Fleet mean residual cannot hold the next item: fresh bin guarantees a home.
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && fitting_bins_count > 0 && progress < 0.7 {
            tight -= 2.0;
        }
        // Sharpen sliver discrimination for the next item's home.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_after = mean_residual / (open_bins_count.max(1) as f64);
            if (best_after as u32) >= next_item_size {
                tight += 1.5;
            } else if progress > 0.75 {
                tight += 1.0;
            }
        }
        score = norm_pr * 20.0 + tight;
    }

    // Mild tie-breaking: prefer bins already below mean residual (tight packing).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Lookahead: if next item cannot use the post-residual but this bin's
    // residual itself is small, favor it (avoid stranding tight bins).
    if next_item_size > post_residual && bin_residual < item_size * 2 {
        score += 8.0 * norm_pr;
    }

    score
}

