pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = norm_pr * norm_pr * 30.0 + norm_pr * 20.0;

    let quarter = bin_capacity / 4;

    // Harmonic class bands on post residual (mutated from parent).
    if post_residual < quarter {
        score += (quarter - post_residual) as f64 * 1.2;
    } else if norm_pr >= 0.5 {
        score -= (pr - cap * 0.5) * 0.8;
    }

    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64 / cap;
        score += gap * gap * 10.0;
        if next_item_size == post_residual {
            score -= 48.0;
            if fitting_bins_count > 1 {
                score -= 6.0;
            }
        } else if post_residual >= next_item_size && bin_residual >= item_size {
            let joint = (post_residual - next_item_size) as f64 / cap;
            score -= (1.0 - joint) * 7.0;
        }
        if post_residual < next_item_size && post_residual > 0 {
            score += 5.5 * (1.0 - norm_pr);
        }
        // near-miss sliver for next item when other bins compete
        if post_residual >= next_item_size && post_residual < next_item_size * 2 && fitting_bins_count > 1 {
            score += 2.5 * norm_pr;
        }
        // two-step lookahead: dead-end residual after next item
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after > 0 && after < item_size {
                score += 3.0 * (1.0 - norm_pr);
            }
        }
    }

    // sliver that cannot host current or next item
    if post_residual > 0 && post_residual < item_size.max(next_item_size) {
        score += 12.0 * (1.0 - norm_pr);
    }
    if post_residual > 0 && norm_pr < 0.02 {
        score -= 9.0;
    }

    // last-chance bin: strongly prefer using the only fitting open bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let mut tight = 6.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            tight = 0.0;
        }
        if fitting_bins_count == 0 {
            tight -= 4.0;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            tight += 3.0;
        }
        if fitting_bins_count > 0 {
            tight += 2.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            tight -= 1.5 / fitting_bins_count as f64;
        }
        if norm_pr < 0.05 {
            tight -= 1.0;
        }
        // eager fresh bin when open bins are nearly saturated
        if mean_residual / cap < 0.03 && fitting_bins_count > 0 {
            tight -= 1.5;
        }
        // late in stream, consolidate into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.9 && fitting_bins_count > 0 {
            tight += 2.0;
        }
        if fitting_bins_count == 1 && next_item_size > 0 && next_item_size > post_residual {
            tight -= 2.5;
        }
        // large items prefer fresh bins
        if item_size > (3 * bin_capacity) / 4 {
            tight -= 2.0;
        }
        score = norm_pr * 20.0 + tight;
    }

    // mean residual coupling: prefer roomier bins
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score += diff * 0.15;
    }

    // late-stream tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
