pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = norm_pr * norm_pr * 30.0 + norm_pr * 20.0;

    // Strong reward for near-perfect fill (2-step lookahead core).
    if post_residual == 0 {
        score -= 1000.0;
    } else if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 800.0;
        } else {
            // Quadratic penalty on mismatch relative to capacity.
            score += (diff / cap) * (diff / cap) * 60.0;
        }
    }

    // Penalize creating small unusable dead space (below typical min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: discourage opening a new bin unless current bin would
    // leave a lot of dead space relative to mean residual.
    if bin_residual == bin_capacity {
        score += 60.0;
        let waste_here = post_residual as f64;
        let waste_avg = (mean_residual - item_size as f64).max(0.0);
        if waste_here < waste_avg * 0.6 {
            score -= 120.0;
        }
        // Extra conservatism early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.2 {
            score += 20.0;
        }
    }

    // Mild tie-breaking: prefer bins already below mean residual (tight packing).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Lookahead: if next item cannot use the post-residual but this bin's
    // residual itself is small, favor it (avoid stranding tight bins).
    if next_item_size > post_residual && bin_residual < item_size * 2 {
        score += 8.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: ideal placement leaves a residual exactly
    // matching the next item size (perfect chain), or zero (perfect fill).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward exact match strongly, penalize mismatch proportionally.
        score += gap * 1.5;

        // Perfect chain bonus: post_residual == next_item_size means next
        // item closes this bin completely.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Dead-space penalty: residual too small for next item and below
        // typical minimum item size -> likely wasted space.
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 20.0;
        }
    } else {
        // Last item: pure tightest-fit behavior.
        score -= 10.0;
    }

    // Reward closing bins tightly (small post_residual relative to mean residual).
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current residuals are badly
    // fragmented (mean residual low relative to item) or no open bin fits well.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize opening new bins mildly by default.
        score += 30.0;
        // But if open bins are nearly full (low mean residual), a new bin
        // becomes reasonable: reduce the penalty.
        score -= (1.0 - fragmentation) * 20.0;
        // Perfect lookahead fit in a fresh bin (item + next item = capacity).
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 40.0;
        }
    }

    // Slight progression bias: later in the stream, favor consolidating
    // (tighter fits matter more as remaining items dwindle).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Prefer bins among many fitting candidates that leave more usable space.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if (next_item_size as u32) > post_residual {
            score += 12.0 * (next_item_size as f64 - post_residual as f64).min(30.0);
        } else if post_residual >= next_item_size as u32 {
            score -= 4.0; // next item can chain into this bin
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Prefer bins whose residual deviates below the mean (consolidate small leftovers).
    let deviation = bin_residual as f64 - mean_residual;
    score += 0.15 * deviation;

    // Early in the stream, be more willing to open new bins (keep flexibility);
    // late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins more as stream progresses,
        // and when many bins are already open.
        let mut new_bin_penalty = 20.0 + 30.0 * progress + 0.5 * open_bins_count as f64;
        // But if the item is large and few bins fit it, opening a bin is attractive.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: mild reward that grows late in the stream.
        score -= 3.0 * progress;
    }

    // Slight preference for bins with moderate residual (avoid fragmenting nearly-full bins
    // with tiny items when a better use may come later).
    if post_residual > 0 && post_residual < 5 {
        score += 6.0; // nearly perfect fit, but tiny residue is fine; small penalty for waste
    }

    // Cap extreme negative scores so ordering stays meaningful.
    if score < -60.0 { score = -60.0; }

    score
}

