        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 1.0 {
            score -= 10.0;
        }
        let _ = awkward;
    }

    // ---- stream progression: early on, be conservative with new bins ----
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.5 * progress * tightness;

    // Prefer denser fleets when many bins are open (consolidation pressure).
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits (small dead space)
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 50.0;

    // Penalize leaving dead space that no plausible item can use
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable gap
    }

    // Lookahead coupling: bonus if next item fits into the post-residual
    if next_item_size > 0 {
        if next_item_size as f64 <= post_residual as f64 {
            score -= 40.0 + 0.5 * (next_item_size as f64);
        } else {
            // post-residual can't hold next item: penalize proportionally wasted
            let waste = post_residual as f64 - (post_residual.min(next_item_size) as f64);
            score += waste * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Many open bins: discourage spreading; prefer dense packing
    let pressure = (open_bins_count as f64) / ((total_items as f64).max(1.0));
    score += pressure * (post_residual as f64) * 0.8;

    // Deviation from mean residual: prefer bins whose residual deviates less (harmonize residuals)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.25;

    // Time horizon: late in the stream, prioritize closing bins tightly
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += progress * (post_residual as f64) * 0.5;

    // New-bin candidate: neutral-ish baseline with mild penalty so it's chosen
    // only when all open bins score poorly
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * progress;
        if fitting_bins_count <= 2 {
            score -= 35.0; // allow new bin when existing options are scarce
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: penalize post_residual, but with a smooth non-linear (quartic) coupling
    // so that very small residuals (dead space) are punished super-linearly.
    let mut score = norm_pr * (1.0 + 2.5 * norm_pr * norm_pr * norm_pr);

    // Smooth interaction: as the stream progresses, prefer tighter fills.
    // Polynomial coupling of progress with post_residual and item size.
    score += 1.2 * progress * norm_pr * (1.0 - norm_item);

    // Reward filling a bin well: smooth bell-shaped reward around small post_residual.
    let fill_quality = 1.0 - norm_pr;
    score -= 1.5 * fill_quality * fill_quality * fill_quality * (0.5 + progress);

    // Lookahead coupling: penalize if next item could have used this residual better.
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / cap;
        let waste = (pr - next_item_size as f64).max(0.0) / cap;
        score += 1.0 * waste * waste * (1.0 - progress);
        // Smooth reward if next item fits snugly in the post residual.
        let snug = (next_norm - norm_pr).abs();
        score -= 0.8 * (1.0 - snug.min(1.0)) * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation).
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 0.5 * open_norm * (norm_pr - mean_residual / cap).abs();

    // New-bin candidate handling: empty bin gets a smooth baseline cost so it is
    // only chosen when open bins would leave large dead space.
    if bin_residual == bin_capacity {
        score += 1.0 + 1.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    let mut score = post;

    // Perfect fit: residual 0 is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic class of the leftover: residuals divisible by common item
    // granularity (e.g. multiples of 10) remain reusable; odd dead space
    // below the minimum item size (1..=5 here) is nearly worthless.
    let dead_zone: u32 = 5;
    if post_residual > 0 && post_residual <= dead_zone {
        score += 45.0; // dead space penalty
    }

    // Modulo-10 class: leftover compatible with typical item sizes stays valuable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Integer-division thresholds: how many minimum items (size ~10) still fit?
    let min_assumed: u32 = 10;
    let slots = post_residual / min_assumed;
    score -= slots as f64 * 4.0;

    // Lookahead coupling: reward if next item exactly fits the post residual
    // (creates a chain), penalize if next item cannot use the leftover class.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
            if post_residual % next_item_size == 0 {
                score -= 8.0; // exact harmonic division
            }
        } else {
            // next item won't fit here; leftover likely stranded
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad residue.
    if bin_residual == bin_capacity {
        // neutral baseline for fresh bin; discourage mildly so existing bins win
        score += 15.0;
        if post_residual % 10 == 0 {
            score -= 10.0;
        }
    }

    // Phase of stream: early on, keep bins flexible (favor larger residuals);
    // late, squeeze tightly (favor smaller residuals) — already implicit, add tilt.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - post) * 0.05;

    // Spread-awareness: if mean residual is high, prefer packing into this bin
    // to consolidate.
    if post < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32;
    let dead_zone = 9u32; // gaps below ~smallest useful item are waste
    if post_residual > 0 && post_residual < dead_zone {
        score += (dead_zone - post_residual) as f64 * 40.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual < item_size {
        // gap too small even for another item of this size -> mild extra penalty
        score += 15.0;
    }

    // Reward tight fits relative to bin capacity (waste ratio penalty).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * 4.0 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: if next item fits the post-residual exactly or well, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < dead_zone {
            score -= 80.0; // next item nearly fills this bin -> great
        } else {
            score -= 20.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot fit here; residual likely dead space
        score += 10.0;
    }

    // Prefer bins with residuals near the item (best-fit flavor) vs. huge residual bins.
    score -= (bin_residual as f64 - item_size as f64).abs() * 0.2;

    // New-bin candidate: only attractive when current item is huge relative to
    // typical residuals or no good fit exists; base cost of opening a bin.
    if bin_residual == bin_capacity {
        let bad_fit_pressure = if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        let waste_if_placed = (bin_capacity - item_size) as f64;
        score = 100.0 + waste_if_placed * 0.5 - bad_fit_pressure;
        // late in stream, opening new bins is costlier
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual
    // matches the next item's size almost exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual >= next_item_size {
            // Perfect two-item chain: post_residual == next_item_size
            let chain_gap = (post - nxt).abs();
            // Strong reward proportional to closeness of the chain match
            score -= 60.0 * (1.0 - chain_gap / bin_capacity as f64).powi(3);
            // Extra bonus for an exact match
            if post_residual == next_item_size {
                score -= 80.0;
            }
        } else {
            // Next item cannot fit here after placement; penalize dead space
            score += 25.0 * (nxt - post) / bin_capacity as f64;
        }
    } else {
        // Last item: minimize waste directly
        score -= 40.0;
    }

    // Compare post_residual against mean residual across open bins:
    // placing in a bin that leaves less than average residual tightens the fleet.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Penalize very small unusable post-residuals (dead space < 10)
    if post_residual < 10 {
        score += 30.0;
    }

    // Late in the stream, tighten packing more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    // New-bin candidate: only open a new bin if no decent fit exists.
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size > 0 && post_residual < next_item_size && fitting_bins_count > 1;
        if !poor_fit {
            score += 100.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly
    let post = post_residual as f64;
    score += 0.35 * (post / bin_capacity as f64).powf(1.6) * bin_capacity as f64;

    // Reward tight fits (small post_residual)
    let tightness = 1.0 - post / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Lookahead: bonus if next item fits exactly in post_residual
    if next_item_size > 0 {
        if (next_item_size as f64 - post).abs() < 0.5 {
            score -= 20.0; // perfect chain
        } else if next_item_size as u32 <= post_residual {
            score -= 8.0; // next item fits in leftover
        } else {
            score += 5.0 * (1.0 - post / bin_capacity as f64); // dead space blocks lookahead
        }
    }

    // Last-chance bin: strongly favor using it before opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin when open bins fit well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (mean_residual.max(1.0));
        let base = 18.0 + 20.0 * progress;
        // If mean residual is large relative to item, prefer existing bins
        score += base + 0.05 * crowding;
        if fitting_bins_count > 0 {
            score += 30.0;
        }
        // Early stream: opening bins is cheaper
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference for fuller bins (small residual relative to mean)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Time horizon: later in stream, be more frugal with new bins
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 * horizon;
    } else {
        score -= 3.0 * horizon;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: post residual, with non-linear polynomial shaping in progress.
    // Early: prefer filling bins tightly (low post_residual strongly favored).
    // Late: dead space matters more, so amplify penalty on large residuals.
    let pr_norm = pr / cap;
    let base = pr * (1.0 + 0.8 * progress * pr_norm * pr_norm);

    // Smooth quadratic coupling: residual tightness vs. stream progress.
    let tightness = 1.0 - pr_norm;
    let coupling = -4.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Last-chance bonus (smooth): penalize alternatives when this is the only fitting bin.
    let last_chance = if fitting_bins_count <= 1 { -8.0 } else { 0.0 };

    // Lookahead: reward leaving space for the next item (smooth Gaussian-like term).
    let nxt = next_item_size as f64;
    let lookahead = if nxt > 0.0 {
        let d = (pr - nxt) / cap;
        -3.0 * (-20.0 * d * d)
    } else {
        0.0
    };

    // Mild penalty for spreading across many open bins relative to mean residual.
    let spread = 0.5 * (pr - mean_residual) / cap * (open_bins_count as f64).sqrt();

    base + coupling + last_chance + lookahead + spread
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" does the leftover fall in?
    // Capacity fractions: quarters of the bin.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Penalize dead space: leftover that is too small to be useful later.
    if post_residual < quarter {
        //越小越差: tiny leftovers are near-waste; add a strong penalty.
        score += (quarter - post_residual) as f64 * 2.5;
    } else if post_residual < half {
        // Mild bonus: leftovers in [quarter, half) can absorb small/medium items.
        score -= (post_residual - quarter) as f64 * 0.3;
    } else {
        // Large leftover: very good, big reward.
        score -= (post_residual - half) as f64 * 0.8;
    }

    // Integer division threshold on post_residual relative to next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: reward if it fits snugly.
            let gap = post_residual - next_item_size;
            if gap < quarter {
                score -= 6.0; // chained snug fit
            } else {
                score -= 2.0;
            }
        } else {
            // Next item won't fit here; penalize proportional to shortfall class.
            let shortfall = next_item_size - post_residual;
            score += (shortfall / quarter.max(1)) as f64 * 1.5;
        }
    }

    // Modulo arithmetic on post_residual: harmonic classes mod 10.
    // Residuals that are multiples of 10 align with typical item granularity.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 1.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item is large
    // and residual here would be awkward. Empty-bin residual equals capacity.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; discount when item is large (>= 3/4 capacity band).
        let base = 12.0;
        if item_size > (3 * bin_capacity) / 4 {
            score += base * 0.4;
        } else if fitting_bins_count > 0 {
            score += base;
        } else {
            score += base * 0.2; // no alternative anyway
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean, it's
    // already fragmented; slight penalty to prefer roomier bins.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score += diff * 0.15;
    }

    // Stream progression: late in the stream, tighten packing (favor tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

