    // Mild preference for bins tighter than the average residual early on,
    // stronger late in the stream (consolidation pressure).
    let tightness = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score += tightness * (5.0 + 20.0 * progress);

    // Small direct reward for high fill ratio of this placement.
    score -= 10.0 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
