        };
        // New bin is attractive if current fit is bad OR next item is huge and
        // deserves a fresh bin.
        score = 55.0 + 60.0 * poor_fit - 70.0 * next_pressure * next_pressure;
        if fitting_bins_count <= 1 {
            // No (or one) alternative: opening a new bin is fine.
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= bin_residual.saturating_sub(0).min(100) && next_item_size > item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear penalty on waste
    let mut score = norm_pr * norm_pr * 30.0 + norm_pr * 20.0;

    // Smooth cubic coupling of post-residual with stream progress:
    // early on, tolerate waste slightly; late, punish it more strongly
    let coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += coupling * norm_pr * 25.0;

    // Reward high fill ratio non-linearly
    let fill = item_size as f64 / cap;
    score -= fill * fill * 15.0;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * coupling;
    }

    // Lookahead: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64 / cap;
        score += gap * gap * 10.0;
        // Reward if next item fits exactly into post-residual
        if next_item_size == post_residual {
            score -= 35.0;
        }
    }

    // Mean-residual deviation: prefer bins near the mean (balance preservation)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 8.0;

    // Mild penalty for many open bins (discourage fragmentation)
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // New-bin candidate: keep it competitive only when current bins are poor fits
    if bin_residual == bin_capacity {
        score = 60.0 - 25.0 * coupling - norm_pr * 0.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    // Buckets: (0,10] tiny dead space (good), (10,30] small, (30,50] half-class,
    // (50,100] large residual (wasteful placement, penalize).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional class of post_residual via integer division thresholds
    let class = post_residual / 10; // 0..=10 harmonic class
    match class {
        0 => score -= 8.0,                       // near-perfect fit
        1 => score -= 5.0,                       // <=20 left, still tight
        2 => score -= 2.0,                       // <=30 left
        3 => {}                                  // neutral
        4 | 5 => score += 3.0,                   // half-empty bin
        _ => score += 8.0,                       // >50 wasted space
    }

    // Modulo arithmetic: residuals that are "friendly" to common item sizes
    // (multiples of 10/20/25) are easier to fill later; reward them.
    if post_residual % 10 == 0 {
        score -= 2.0;
    } else if post_residual % 5 == 0 {
        score -= 1.0;
    }

    // Lookahead coupling: does the next item fit the post_residual?
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            // Next item chains nicely; reward proportionally to how snugly.
            let snug = (next_item_size as f64) / pr.max(1.0);
            score -= 3.0 + 4.0 * snug;
        } else {
            // Next item won't fit here; penalize if this bin would be left awkward.
            let gap = (next_item_size as f64) - pr;
            if gap < 20.0 {
                score += 2.0 + gap * 0.1; // "just missed" dead space is worst
            }
        }
    } else {
        // Last item: just minimize post_residual hard.
        score += pr * 0.05;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 0.1 * (bin_residual as f64 - pr);
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a decent fit. Base cost of a new bin:
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (post_residual as f64);
        // If existing bins are crowded on average, new bin becomes cheaper.
        score -= (mean_residual / cap).min(1.0) * 12.0;
        // Many open bins with high mean residual -> prefer reusing.
        if open_bins_count > 2 && mean_residual > 0.35 * cap {
            score += 10.0;
        }
    } else {
        // Slight preference for bins below mean residual (balance load) early on.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += dev * (6.0 * (1.0 - progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

