    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current residuals are all badly fragmented
    // (i.e., item barely fits anywhere and mean residual is very small).
    if bin_residual == bin_capacity {
        score += 12.0;
        if mean_residual < item_size as f64 * 0.5 && fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
