    // leave a lot of dead space relative to mean residual.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Allow new bin when all open bins would waste badly.
        let waste_here = post_residual as f64;
        let waste_avg = (mean_residual - item_size as f64).max(0.0);
        if waste_here < waste_avg * 0.6 {
