    // Mild tie-breaking: prefer bins already below mean residual (tight packing).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Early stream: be slightly conservative about opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity && progress < 0.2 {
        score += 20.0;
    }

    score
}

