    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * ((pr - mean_residual).abs() / cap);

    // New-bin candidate: prefer it early or when item leaves a very poor residual
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress) - 20.0 * norm_pr * (1.0 - item_size as f64 / cap);
