        } else if pr % 20 >= 11 && pr % 20 <= 19 {
            score += 3.0;
        }
        // integer-division thresholds: leftover big enough for half a bin is great
        if pr >= bin_capacity / 2 {
            score -= 5.0;
        } else if pr >= bin_capacity / 4 {
            score -= 2.0;
        }
    } else {
        // perfect fit
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // harmonic class match: next item divides the leftover evenly
            if next_item_size > 0 && pr % next_item_size == 0 {
                score -= 8.0;
            } else {
                score -= 2.0;
            }
        } else {
            // next item won't fit here: slight penalty for tight residual
            score += 1.5;
