    // New-bin candidate handling: only attractive early in the stream or when
    // open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        // Opening a new bin is penalized more as the stream matures and as
        // existing bins are still loosely filled.
        score += 4.0 + 14.0 * progress * mean_fill;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 3.0; // big next item makes a fresh bin slightly more attractive
        }
    }

    // Mild pressure to consolidate: prefer bins tighter than the mean residual.
    let resid_gap = mean_residual - bin_residual as f64;
    score += 0.05 * resid_gap;

    // Small tie-breaker on tightness relative to capacity fractions.
    score += 0.02 * ((bin_residual as f64 / cap) * 10.0).floor();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
