        // NEW: reward when the residual is "usable" — next item fits with little waste
        else if next_item_size <= post_residual {
            let waste = (post_residual - next_item_size) as f64 / cap;
            score -= (1.0 - waste) * 8.0;
        }
        // NEW: if next item is large relative to capacity, prefer bins that stay
        // compact so a future bin can hold it (avoid scattering small residuals)
        if next_item_size as f64 > 0.6 * cap && norm_pr > 0.0 && norm_pr < (next_item_size as f64 / cap) {
            score += 6.0 * coupling;
        }
    }

    // Mean-residual deviation: prefer bins near the mean (balance preservation)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 8.0;

    // Mild penalty for many open bins (discourage fragmentation)
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Perfect-fit bonus: leaving exactly zero residual is ideal
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate: adapt its score to stream phase and open-bin pressure.
    // Early with few bins: opening a new bin is cheap. Late / many bins: require
    // open bins to be genuinely poor fits before allowing a new bin.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score = 55.0 - 20.0 * coupling + pressure * 4.0;
        // If the item would leave a very tight residual in an existing bin,
        // a fresh bin is more attractive; if it fits snugly, discourage new bin.
        let snug = (bin_residual - item_size) as f64 / cap; // = 1 - fill for new bin
        score += snug * snug * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
