    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 8.0;

    // Consolidation pressure: prefer bins tighter than the mean residual
    let resid_gap = mean_residual - bin_residual as f64;
    score += 0.05 * resid_gap;

    // Tightness tie-breaker
    score += 0.02 * ((bin_residual as f64 / cap) * 10.0).floor();

    // Mild fragmentation penalty grows with open bin count
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // New-bin candidate: competitive only early or when open bins are tight
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score = 60.0 - 25.0 * coupling * mean_fill;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0;
        }
        // if only one bin fits the item, don't open a new one lightly
        if fitting_bins_count >= 1 {
            score += 8.0;
        }
    }

    score
}

