        if post_residual >= next_item_size && bin_residual >= item_size {
            let joint = (post_residual - next_item_size) as f64 / cap;
            score -= (1.0 - joint) * 6.0;
        }
        // penalize bins that could hold next item but item would leave a huge hole
        if nxt > pr && pr > 0.0 {
            score += 4.0; // this bin will strand residual; slight penalty
        }
    }

    // scarcity pressure: when few bins can fit the item, favor whichever fits best
    if fitting_bins_count > 1 {
        score -= 2.0 / fitting_bins_count as f64;
    } else if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // avoid wasting near-full bins on items that leave large dead space
    let dead = (post_residual as f64 - it).max(0.0) / cap;
    if dead > 0.5 {
        score += (dead - 0.5) * 12.0;
    }

    // tight-fit reward: item nearly fills the bin completely
    let fill_ratio = it / (bin_residual as f64);
    if fill_ratio > 0.85 {
        score -= (fill_ratio - 0.85) * 25.0;
    }

    // new-bin candidate: only open a new bin when it's genuinely better,
    // i.e., when no open bin gives a tight fit and mean residual is high
    if bin_residual == bin_capacity {
        let slack = (pr - it) / cap;
        if fitting_bins_count > 0 && slack < 0.25 {
            score += 60.0; // keep using open bins with decent fits
        } else {
            score += 8.0 + norm_pr * 4.0; // mild penalty, allows opening when needed
        }
    }

    // late-stream consolidation: prefer emptier bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 && mean_residual > 0.0 {
        score += norm_pr * (progress - 0.7) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
