    // Strong reward for perfect fill.
    if post_residual == 0 {
        score -= 1000.0;
    } else if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 800.0;
        } else {
            // One-sided gap: only penalize leftover space the next item cannot use.
            let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64 / cap;
            score += gap * gap * 10.0;
            // Extra penalty when the stranded gap is small and unusable.
            if post_residual < item_size.max(1) {
