    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin: favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0 * (1.0 - norm_pr);
