    }
    // Near-perfect bin: reward tiny leftovers
    if post_residual > 0 && norm_pr < 0.02 {
        score -= 9.0;
    }

    // Modulo alignment bonus
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 1.0;
    }

    // Last-chance bin: strongly prefer the only fitting open bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate scoring
    if bin_residual == bin_capacity {
        let mut tight = 6.0;
