            score += 3.0 * (1.0 - norm_pr) ;
        }
        // NEW: chain-exactness — placing next here leaves a residual that exactly
        // equals a small plausible item (1..=8), which is nearly a guaranteed fit
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if after >= 1 && after <= 8 {
                score -= 3.5 ;
            }
        }
        // NEW: dead-space fraction penalty — measure how much of this bin's
        // residual would become unusable (< smallest plausible item) after the
        // next item lands here; penalize proportionally to how full the fleet is
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if after > 0 && after < 1 {
                score += 4.0 * (1.0 - norm_pr) ;
            }
        }
    }

    if post_residual > 0 && post_residual < item_size.max(next_item_size) {
        score += 12.0 * (1.0 - norm_pr) ;
    }
    if post_residual > 0 && norm_pr < 0.02 {
        score -= 9.0 ;
    }

    if bin_residual == bin_capacity {
        let mut tight = 6.0 ;
        if next_item_size > 0 && next_item_size <= post_residual {
            tight = 0.0 ;
        }
        if fitting_bins_count == 0 {
            tight -= 4.0 ;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            tight += 3.0 ;
        }
        if fitting_bins_count > 0 {
            tight += 2.0 ;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let sliver = fitting_bins_count as f64 ;
            tight -= 1.5 * (sliver.recip()) ;
        }
        if norm_pr < 0.05 {
            tight -= 1.0 ;
        }
        if mean_residual / cap < 0.03 && fitting_bins_count > 0 {
            tight -= 1.5 ;
        }
        let progress = step_index as f64 / (total_items.max(1) as f64) ;
        if progress > 0.9 && fitting_bins_count > 0 {
            tight += 2.0 ;
        }
        if fitting_bins_count == 1 && next_item_size > 0 && next_item_size > post_residual {
            tight -= 2.5 ;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if (avg_fit as u32) < item_size * 2 && progress < 0.85 {
                tight -= 1.0 ;
            }
        }
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && fitting_bins_count > 0 && progress < 0.7 {
            tight -= 2.0 ;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_after = mean_residual / (open_bins_count.max(1) as f64) ;
            if (best_after as u32) >= next_item_size {
                tight += 1.5 ;
            } else if progress > 0.75 {
                tight += 1.0 ;
            }
        }
        if progress > 0.8 && fitting_bins_count > 0 {
            tight += 2.5 * progress ;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if avg_fit < next_item_size as f64 + 1.0 && progress < 0.5 {
                tight -= 1.0 ;
            }
        }
