        // bin if no existing bin can host BOTH the current and the next item;
        // otherwise push hard into the fleet to avoid a stranded near-empty bin
        if progress > 0.7 && next_item_size > 0 && fitting_bins_count > 0 {
            let can_chain = (mean_residual as u32) >= next_item_size + 1 ;
            if can_chain {
                tight += 1.8 ;
            }
        }
        // NEW: early-stream bin budgeting — when the fleet is still small relative
        // to remaining items, be slightly more willing to open bins to keep slack
        // distributed (reduces future dead space); tighten as fleet grows
        if progress < 0.3 && open_bins_count > 0 {
            let items_per_bin = (total_items / open_bins_count.max(1)) as f64 ;
            if items_per_bin > 4.0 {
                tight -= 0.8 ;
            }
        }
        score = norm_pr * 20.0 + tight ;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let pr = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let norm_pr = pr / cap ;
    let mut score = norm_pr * norm_pr * 30.0 + norm_pr * 20.0 ;

    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64 / cap ;
        score += gap * gap * 10.0 ;
        if next_item_size == post_residual {
            score -= 48.0 ;
        } else if next_item_size as f64 > post_residual as f64 && post_residual < item_size as f64 * 0.5 {
            score += 8.0 * norm_pr ;
        }
        if post_residual >= next_item_size && bin_residual >= item_size {
            let joint = (post_residual - next_item_size) as f64 / cap ;
            score -= (1.0 - joint) * 7.0 ;
        }
        if next_item_size as f64 > pr && norm_pr > 0.15 {
            score += norm_pr * 6.0 ;
        }
        if post_residual < next_item_size && post_residual > 0 {
            score += 5.5 * (1.0 - norm_pr) ;
        }
        if post_residual >= next_item_size && post_residual < next_item_size * 2 && fitting_bins_count > 1 {
            score += 2.5 * norm_pr ;
        }
        if next_item_size == post_residual && fitting_bins_count > 1 {
            score -= 6.0 ;
        }
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if after > 0 && after < item_size {
                score += 3.0 * (1.0 - norm_pr) ;
            }
        }
        // dead-end metric: residual left after hosting the next item is only
        // useful if it can host at least a small item; weight by fleet slack
        if post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64 / cap ;
            let usable = if after > 0.0 { 1.0 } else { 0.0 } ;
            let fleet_slack = (mean_residual / cap).min(1.0) ;
            score += (1.0 - after) * usable * (1.5 + 2.0 * (1.0 - fleet_slack)) ;
        }
        // reward bins whose post-residual still covers average upcoming demand
        if post_residual >= next_item_size {
            let avg_next = mean_residual / (open_bins_count.max(1) as f64) ;
            if next_item_size as f64 <= avg_next * 1.5 {
                score -= 1.2 * norm_pr ;
            }
        }
        // near-perfect-fill bonus — item exactly leaves a tiny unusable crumb
        if post_residual > 0 && post_residual < 4 {
            score -= 4.0 + 3.0 * (1.0 - norm_pr) ;
        }
        // exact-fit lookahead chain: residual left equals a plausible small item
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if after > 0 && after <= item_size && after <= next_item_size {
                score -= 4.0 ;
            }
        }
        // penalize awkward slivers just above next item, scaled by alternatives
        if post_residual > next_item_size && post_residual < next_item_size + 4 && fitting_bins_count > 1 {
            score += 3.0 * (1.0 - norm_pr) ;
        }
        // combined lookahead — if this bin's residual after taking the item
        // plus the fleet's average slack can host the next item, prefer it mildly
        if post_residual >= item_size {
            let slack = mean_residual / (open_bins_count.max(1) as f64) ;
            if (post_residual - item_size) as f64 + slack >= next_item_size as f64 {
                score -= 1.0 ;
            }
        }
        // exact-fit chain reward — post_residual exactly equals next item,
        // leaving zero waste; amplify with scarcity of alternatives
        if post_residual == next_item_size {
            score -= 2.0 + 1.0 / (fitting_bins_count.max(1) as f64) ;
        }
        // penalize large post-residuals that cannot host the next item
        // (waste that will persist), stronger when fleet slack is low
        if post_residual > 0 && post_residual < next_item_size {
            let fleet_tight = (mean_residual / cap).min(1.0) ;
            score += 2.0 * (1.0 - fleet_tight) * norm_pr ;
        }
        // NEW: reward bins whose post-residual can host both the next item and
        // roughly the average follow-up demand (two-step lookahead)
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            let avg_next = mean_residual / (open_bins_count.max(1) as f64) ;
            if (after as f64) >= avg_next * 0.5 && after >= item_size / 2 {
                score -= 2.0 ;
            }
        }
    }

    if post_residual > 0 && post_residual < item_size.max(next_item_size) {
        score += 12.0 * (1.0 - norm_pr) ;
    }
    if post_residual > 0 && norm_pr < 0.02 {
        score -= 9.0 ;
    }

    if bin_residual == bin_capacity {
        let mut tight = 6.0 ;
        if next_item_size > 0 && next_item_size <= post_residual {
            tight = 0.0 ;
        }
        if fitting_bins_count == 0 {
            tight -= 4.0 ;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            tight += 3.0 ;
        }
        if fitting_bins_count > 0 {
            tight += 2.0 ;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let sliver = fitting_bins_count as f64 ;
            tight -= 1.5 * (sliver.recip()) ;
        }
        if norm_pr < 0.05 {
            tight -= 1.0 ;
        }
        if mean_residual / cap < 0.03 && fitting_bins_count > 0 {
            tight -= 1.5 ;
        }
        let progress = step_index as f64 / (total_items.max(1) as f64) ;
        if progress > 0.9 && fitting_bins_count > 0 {
            tight += 2.0 ;
        }
        if fitting_bins_count == 1 && next_item_size > 0 && next_item_size > post_residual {
            tight -= 2.5 ;
        }
        // opening a fresh bin is cheaper when fitting bins leave only slivers
        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if (avg_fit as u32) < item_size * 2 && progress < 0.85 {
                tight -= 1.0 ;
            }
        }
        // mid-stream: fresh bin guarantees a home for the next item
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && fitting_bins_count > 0 && progress < 0.7 {
            tight -= 2.0 ;
        }
        // sharpen sliver discrimination
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_after = mean_residual / (open_bins_count.max(1) as f64) ;
            if (best_after as u32) >= next_item_size {
                tight += 1.5 ;
            } else if progress > 0.75 {
                tight += 1.0 ;
            }
        }
        // late-stream conservation — near the end, opening a new bin is almost
        // never recoverable; push harder toward existing fits
        if progress > 0.8 && fitting_bins_count > 0 {
            tight += 2.5 * progress ;
        }
        // early-stream exploration — keep residual distribution wide early
        if progress < 0.1 && fitting_bins_count > 2 {
            tight -= 0.5 ;
        }
        // if only fitting bins would leave dead slivers below smallest item,
        // a fresh bin is genuinely better (dampened to avoid bin blowup)
        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if avg_fit < next_item_size as f64 + 1.0 && progress < 0.5 {
                tight -= 1.0 ;
            }
        }
        // if every fitting bin would leave a sliver smaller than the smallest
        // plausible item after taking this item, opening fresh is better
        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if (avg_fit as u32) >= item_size && (avg_fit as u32) < item_size + 3 && progress < 0.6 {
                tight -= 1.5 ;
            }
        }
        score = norm_pr * 20.0 + tight ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable
    // (items are 1..=100, but gaps < ~12 rarely accept future items well).
    if post_residual > 0 {
        if post_residual <= 10 {
            // Hard dead-space penalty, scaled by how "dead" the gap is.
            score += (11.0 - post_residual as f64) * 15.0;
        } else if post_residual <= 20 {
            score += (21.0 - post_residual as f64) * 4.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward fits that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap that wastes the lookahead opportunity.
        score += 8.0;
    }

    // Reward tight relative fit (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: prefer reusing bins when many are open,
    // but ease pressure when this is the last fitting bin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 2.0 + 3.0 * progress;
    if fitting_bins_count <= 1 {
        score -= pressure * 2.0;
    } else {
        score += (open_bins_count as f64) * pressure * 0.15;
    }

    // Prefer bins with below-mean residual (more crowded bins first,
    // keeping roomy bins flexible) — classic best-fit-with-mean shaping.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New empty bin candidate: only attractive if current bin would leave
    // a dead gap or no open bin fits well.
    if bin_residual == bin_capacity {
        if post_residual > 0 && post_residual <= 10 {
            score -= 40.0; // better to open fresh bin than create dead space
        } else {
            score += 25.0 + 0.5 * open_bins_count as f64; // discourage opening by default
        }
    }

    score
}

