pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match between post_residual and next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect chain fit: strong reward
        if post_residual as u32 == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here later: mild reward proportional to tightness
            score -= 10.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize
            score += 0.6 * (nxt - post_residual as f64);
        }
    }

    // Penalize post_residual far below mean residual (creating outlier dead space)
    score += 0.3 * (mean_residual - post_residual as f64).abs().min(50.0);

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when many bins already open or item is huge
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * item_size as f64;
    }

    // Slight preference for tighter fits overall
    score += 0.2 * (post_residual as f64 / bin_capacity as f64);

    score
}

