        }
        if next_item_size == post_residual && fitting_bins_count > 1 {
            score -= 6.0 ;
        }
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if after > 0 && after < item_size {
                score += 3.0 * (1.0 - norm_pr) ;
            }
        }
        if post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64 / cap ;
            let usable = if after > 0.0 { 1.0 } else { 0.0 } ;
            let fleet_slack = (mean_residual / cap).min(1.0) ;
            score += (1.0 - after) * usable * (1.5 + 2.0 * (1.0 - fleet_slack)) ;
        }
        if post_residual >= next_item_size {
            let avg_next = mean_residual / (open_bins_count.max(1) as f64) ;
            if next_item_size as f64 <= avg_next * 1.5 {
                score -= 1.2 * norm_pr ;
            }
        }
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if after > 0 && after <= item_size && after <= next_item_size {
                score -= 4.0 ;
            }
        }
        if post_residual > next_item_size && post_residual < next_item_size + 4 && fitting_bins_count > 1 {
            score += 3.0 * (1.0 - norm_pr) ;
        }
        // dead-space ratio: fraction of bin permanently unusable if next item
        // lands elsewhere; stronger weight late in the stream where waste is
        // unrecoverable
        if post_residual < next_item_size && post_residual > 0 {
            let dead = (next_item_size - post_residual) as f64 / cap ;
            let urgency = 14.0 + 6.0 * progress ;
            score += dead * urgency * (1.0 - norm_pr) ;
        }
        // two-step lookahead chain: reward bins that can host next item AND
        // leave room for a follow-up of at least the current item's class
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if after >= item_size.min(next_item_size) && after > 0 {
                score -= 2.0 * (1.0 - norm_pr) ;
            }
        }
        // exact-fill chain bonus: post-residual exactly matches next item —
        // zero-waste pairing, escalate bonus as stream progresses
        if post_residual == next_item_size {
            score -= 4.0 + 4.0 * progress ;
        }
    }

    if post_residual > 0 && post_residual < item_size.max(next_item_size) {
        score += 12.0 * (1.0 - norm_pr) ;
    }
    if post_residual > 0 && norm_pr < 0.02 {
        score -= 9.0 ;
    }

    if bin_residual == bin_capacity {
        let mut tight = 6.0 ;
        if next_item_size > 0 && next_item_size <= post_residual {
            tight = 0.0 ;
        }
        if fitting_bins_count == 0 {
            tight -= 4.0 ;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            tight += 3.0 ;
        }
        if fitting_bins_count > 0 {
            tight += 2.0 ;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let sliver = fitting_bins_count as f64 ;
            tight -= 1.5 * (sliver.recip()) ;
