        if mean_residual / cap < 0.03 && fitting_bins_count > 0 {
            tight -= 1.5 ;
        }
        if progress > 0.9 && fitting_bins_count > 0 {
            tight += 2.0 ;
        }
        if fitting_bins_count == 1 && next_item_size > 0 && next_item_size > post_residual {
            tight -= 2.5 ;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if (avg_fit as u32) < item_size * 2 && progress < 0.85 {
                tight -= 1.0 ;
            }
        }
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && fitting_bins_count > 0 && progress < 0.7 {
            tight -= 2.0 ;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_after = mean_residual / (open_bins_count.max(1) as f64) ;
            if (best_after as u32) >= next_item_size {
                tight += 1.5 ;
            } else if progress > 0.75 {
                tight += 1.0 ;
            }
        }
        if progress > 0.8 && fitting_bins_count > 0 {
            tight += 2.5 * progress ;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if avg_fit < next_item_size as f64 + 1.0 && progress < 0.5 {
                tight -= 1.0 ;
            }
        }
        // fresh-bin escape: if every fitting bin would leave a sliver smaller
        // than a useful chunk of the current item, a fresh bin is cheaper —
        // but only early/mid stream where the new bin can still be filled
        if fitting_bins_count > 0 && next_item_size > 0 && progress < 0.65 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if avg_fit > next_item_size as f64 && avg_fit < next_item_size as f64 + item_size as f64 * 0.35 {
                tight -= 1.8 ;
            }
        }
        // late-stream: strongly prefer any existing fit over opening a bin
        // that will almost certainly end mostly empty
        if progress > 0.7 && fitting_bins_count > 0 {
            tight += 1.5 * progress ;
        }
        score = norm_pr * 20.0 + tight ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual is good, but amplify).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely better.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * mean_residual;
        // Early in stream, new bins are cheaper; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 18.0 * (1.0 - progress);
    }

    // Slight preference for bins below mean residual (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Prefer larger residuals slightly (save tight bins for tight items).
    score -= 0.03 * bin_residual as f64;

    score
}

