pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear (quadratic/cubic) shaping.
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth coupling with stream progress: early on, tolerate larger residuals
    // (keep bins flexible); late in the stream, tighten aggressively.
    let progress_tightening = 1.0 - 0.5 * progress * progress;
    score *= progress_tightening;

    // Reward leaving a residual that matches the lookahead item (k=2 lookahead fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let match_bonus = -8.0 * (-gap / 15.0) * (-gap / 15.0); // smooth Gaussian-like reward
        score += match_bonus * (1.0 + progress);
    }

    // Penalize deviation from the mean residual across open bins (balance residual mass),
    // scaled smoothly by the number of open bins.
    let balance_penalty = ((pr - mean_residual) / cap).abs();
    score += 12.0 * balance_penalty * balance_penalty * (open_bins_count as f64).ln().max(1.0);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Slight penalty for opening a new bin when many bins are already open.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (open_bins_count as f64).sqrt();
    }

    score
}

