        if next_item_size as f64 > pr && norm_pr > 0.15 {
            score += norm_pr * 6.0 ;
        }
        if post_residual < next_item_size && post_residual > 0 {
            score += 5.5 * (1.0 - norm_pr) ;
        }
        if post_residual >= next_item_size && post_residual < next_item_size * 2 && fitting_bins_count > 1 {
            score += 2.5 * norm_pr ;
        }
        if next_item_size == post_residual && fitting_bins_count > 1 {
            score -= 6.0 ;
        }
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if after > 0 && after < item_size {
                score += 3.0 * (1.0 - norm_pr) ;
            }
        }
        if post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64 / cap ;
            let usable = if after > 0.0 { 1.0 } else { 0.0 } ;
            let fleet_slack = (mean_residual / cap).min(1.0) ;
            score += (1.0 - after) * usable * (1.5 + 2.0 * (1.0 - fleet_slack)) ;
        }
        if post_residual >= next_item_size {
            let avg_next = mean_residual / (open_bins_count.max(1) as f64) ;
            if next_item_size as f64 <= avg_next * 1.5 {
                score -= 1.2 * norm_pr ;
            }
        }
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if after > 0 && after <= item_size && after <= next_item_size {
                score -= 4.0 ;
            }
        }
        if post_residual > next_item_size && post_residual < next_item_size + 4 && fitting_bins_count > 1 {
            score += 3.0 * (1.0 - norm_pr) ;
        }
        // dead-space ratio: residual permanently unusable if next item lands elsewhere
        if post_residual < next_item_size && post_residual > 0 {
            let dead = (next_item_size - post_residual) as f64 / cap ;
            score += dead * 14.0 * (1.0 - norm_pr) ;
        }
        // two-step lookahead chain: after hosting next item, room for a follow-up
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if after >= item_size.min(next_item_size) && after > 0 {
                score -= 2.0 * (1.0 - norm_pr) ;
            }
        }
        // NEW: exact-match synergy — bin whose post-residual equals next item AND
        // whose current fit leaves exactly next_item_size after this placement is
        // a perfect chain; reward strongly when alternatives exist
        if post_residual == next_item_size && fitting_bins_count >= 1 {
            score -= 2.0 * (fitting_bins_count.min(3) as f64) ;
        }
        // NEW: penalize bins that fit the item but leave a residual that cannot
        // hold the next item while other bins could host both (dead-space trade)
        if post_residual >= item_size && post_residual < next_item_size && next_item_size > item_size {
            score += 3.0 ;
        }
    }

    if post_residual > 0 && post_residual < item_size.max(next_item_size) {
        score += 12.0 * (1.0 - norm_pr) ;
    }
    if post_residual > 0 && norm_pr < 0.02 {
        score -= 9.0 ;
    }

    if bin_residual == bin_capacity {
        let mut tight = 6.0 ;
        if next_item_size > 0 && next_item_size <= post_residual {
            tight = 0.0 ;
        }
        if fitting_bins_count == 0 {
            tight -= 4.0 ;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            tight += 3.0 ;
        }
        if fitting_bins_count > 0 {
            tight += 2.0 ;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let sliver = fitting_bins_count as f64 ;
            tight -= 1.5 * (sliver.recip()) ;
        }
        if norm_pr < 0.05 {
            tight -= 1.0 ;
        }
        if mean_residual / cap < 0.03 && fitting_bins_count > 0 {
            tight -= 1.5 ;
        }
        let progress = step_index as f64 / (total_items.max(1) as f64) ;
        if progress > 0.9 && fitting_bins_count > 0 {
            tight += 2.0 ;
        }
        if fitting_bins_count == 1 && next_item_size > 0 && next_item_size > post_residual {
            tight -= 2.5 ;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if (avg_fit as u32) < item_size * 2 && progress < 0.85 {
                tight -= 1.0 ;
            }
        }
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && fitting_bins_count > 0 && progress < 0.7 {
            tight -= 2.0 ;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_after = mean_residual / (open_bins_count.max(1) as f64) ;
            if (best_after as u32) >= next_item_size {
                tight += 1.5 ;
            } else if progress > 0.75 {
                tight += 1.0 ;
            }
        }
        if progress > 0.8 && fitting_bins_count > 0 {
            tight += 2.5 * progress ;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if avg_fit < next_item_size as f64 + 1.0 && progress < 0.5 {
                tight -= 1.0 ;
            }
        }
        // if every fitting bin would leave a sliver smaller than the current
        // item class, a fresh bin is cheaper — but only early/mid stream
        if fitting_bins_count > 0 && next_item_size > 0 && progress < 0.65 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if avg_fit > next_item_size as f64 && avg_fit < next_item_size as f64 + item_size as f64 * 0.35 {
                tight -= 1.8 ;
            }
        }
        // NEW: late-stream hard conservation — after 90% of stream, a new bin is
        // almost never recoverable; raise the bar sharply
        if progress > 0.9 {
            tight += 1.5 * progress ;
        }
        // NEW: early stream with many open bins — prefer consolidating into
        // existing bins rather than spawning fresh capacity
        if progress < 0.25 && open_bins_count > 4 && fitting_bins_count > 0 {
            tight += 1.0 ;
        }
        score = norm_pr * 20.0 + tight ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer bins with small post_residual (tight packing).
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "useful"
    // classes (multiples of common size bands) are less dead-space prone.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly favored.
        score -= 200.0;
    } else {
        // Class by integer division into capacity-fraction bands.
        let band = pr / 10; // 0..=10
        match band {
            0 => { score -= 40.0; }        // 1..9: nearly full, excellent
            1 => { score -= 15.0; }        // 10..19: good
            2 | 3 => { score -= 5.0; }     // 20..39: moderate
            4 | 5 => { score += 10.0; }    // 40..59: half empty, wasteful
            6 | 7 => { score += 20.0; }    // 60..79: poor
            _ => { score += 35.0; }        // 80..99: very poor
        }
        // Modulo harmonic: leftovers divisible by small common item sizes
        // (10, 20, 25, 50) are reusable by future small items.
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 25 == 0 { score -= 8.0; }
        if pr % 50 == 0 { score -= 8.0; }
    }

    // Lookahead: if the next item fits exactly in the post-residual class,
    // reward; if next item is large and post_residual too small, penalize
    // only mildly (next item can go elsewhere).
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item could chain into this bin: harmonic match bonus.
            if pr % next_item_size == 0 {
                score -= 25.0; // exact chaining
            } else {
                score -= 8.0;
            }
        } else {
            // Post-residual smaller than next item: residual becomes a
            // stranded class unless it is tiny.
            if pr > 0 && pr < 10 {
                score += 5.0; // tiny stranded sliver
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Penalize opening a new bin when many bins are open and the stream is
    // progressing, unless the item is huge relative to capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let huge_item = (item_size as f64 / bin_capacity as f64) > 0.8;
        if open_bins_count > 0 && fitting_bins_count > 0 && !huge_item {
            score += 60.0 + 40.0 * progress;
        } else if open_bins_count > 0 && !huge_item {
            score += 15.0;
        }
        // Early stream: opening bins is cheap to build a good portfolio.
        if progress < 0.1 {
            score -= 20.0;
        }
    }

    // Coupling with mean residual: if this bin's residual is far below the
    // mean, it is already crowded — finishing it off is good.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= (diff * 0.5).min(25.0);
    } else {
        score += ((-diff) * 0.3).min(20.0);
    }

    // Mild preference to keep the number of open bins from exploding.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let pr = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let norm_pr = pr / cap ;
    let mut score = norm_pr * norm_pr * 30.0 + norm_pr * 20.0 ;

    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64 / cap ;
        score += gap * gap * 10.0 ;
        if next_item_size == post_residual {
            score -= 48.0 ;
        } else if next_item_size as f64 > post_residual as f64 && post_residual < item_size as f64 * 0.5 {
            score += 8.0 * norm_pr ;
        }
        if post_residual >= next_item_size && bin_residual >= item_size {
            let joint = (post_residual - next_item_size) as f64 / cap ;
            score -= (1.0 - joint) * 7.0 ;
        }
        if next_item_size as f64 > pr && norm_pr > 0.15 {
            score += norm_pr * 6.0 ;
        }
        if post_residual < next_item_size && post_residual > 0 {
            score += 5.5 * (1.0 - norm_pr) ;
        }
        if post_residual >= next_item_size && post_residual < next_item_size * 2 && fitting_bins_count > 1 {
            score += 2.5 * norm_pr ;
        }
        if next_item_size == post_residual && fitting_bins_count > 1 {
            score -= 6.0 ;
        }
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if after > 0 && after < item_size {
                score += 3.0 * (1.0 - norm_pr) ;
            }
        }
        // dead-end metric: residual left after hosting the next item is only
        // useful if it can host at least a small item; weight by fleet slack
        if post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64 / cap ;
            let usable = if after > 0.0 { 1.0 } else { 0.0 } ;
            let fleet_slack = (mean_residual / cap).min(1.0) ;
            score += (1.0 - after) * usable * (1.5 + 2.0 * (1.0 - fleet_slack)) ;
        }
        // reward bins whose post-residual still covers average upcoming demand
        if post_residual >= next_item_size {
            let avg_next = mean_residual / (open_bins_count.max(1) as f64) ;
            if next_item_size as f64 <= avg_next * 1.5 {
                score -= 1.2 * norm_pr ;
            }
        }
        // near-perfect-fill bonus — item exactly leaves a tiny unusable crumb
        if post_residual > 0 && post_residual < 4 {
            score -= 4.0 + 3.0 * (1.0 - norm_pr) ;
        }
        // two-step lookahead — post-residual can also hold approximated next demand
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if (after as f64) >= mean_residual / (open_bins_count.max(1) as f64) * 0.5 && after >= item_size / 2 {
                score -= 2.0 ;
            }
        }
        // exact-fit lookahead chain: residual left equals a plausible small item
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if after > 0 && after <= item_size && after <= next_item_size {
                score -= 4.0 ;
            }
        }
        // penalize awkward slivers just above next item, scaled by alternatives
        if post_residual > next_item_size && post_residual < next_item_size + 4 && fitting_bins_count > 1 {
            score += 3.0 * (1.0 - norm_pr) ;
        }
        // combined lookahead — if this bin's residual after taking the item
        // plus the fleet's average slack can host the next item, prefer it mildly
        if post_residual >= item_size {
            let slack = mean_residual / (open_bins_count.max(1) as f64) ;
            if (post_residual - item_size) as f64 + slack >= next_item_size as f64 {
                score -= 1.0 ;
            }
        }
        // exact-fit chain reward — post_residual exactly equals next item,
        // leaving zero waste; amplify with scarcity of alternatives
        if post_residual == next_item_size {
            score -= 2.0 + 1.0 / (fitting_bins_count.max(1) as f64) ;
        }
        // penalize large post-residuals that cannot host the next item
        // (waste that will persist), stronger when fleet slack is low
        if post_residual > 0 && post_residual < next_item_size {
            let fleet_tight = (mean_residual / cap).min(1.0) ;
            score += 2.0 * (1.0 - fleet_tight) * norm_pr ;
        }
        // NEW: keep the bin's post-residual aligned with the fleet's average
        // residual so future items still find homes — mild compaction pull
        if post_residual >= next_item_size {
            let avg_res = mean_residual / (open_bins_count.max(1) as f64) ;
            let drift = ((pr - avg_res).abs()) / cap ;
            score += drift * 1.5 ;
        }
    }

    if post_residual > 0 && post_residual < item_size.max(next_item_size) {
        score += 12.0 * (1.0 - norm_pr) ;
    }
    if post_residual > 0 && norm_pr < 0.02 {
        score -= 9.0 ;
    }

    if bin_residual == bin_capacity {
        let mut tight = 6.0 ;
        if next_item_size > 0 && next_item_size <= post_residual {
            tight = 0.0 ;
        }
        if fitting_bins_count == 0 {
            tight -= 4.0 ;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            tight += 3.0 ;
        }
        if fitting_bins_count > 0 {
            tight += 2.0 ;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let sliver = fitting_bins_count as f64 ;
            tight -= 1.5 * (sliver.recip()) ;
        }
        if norm_pr < 0.05 {
            tight -= 1.0 ;
        }
        if mean_residual / cap < 0.03 && fitting_bins_count > 0 {
            tight -= 1.5 ;
        }
        let progress = step_index as f64 / (total_items.max(1) as f64) ;
        if progress > 0.9 && fitting_bins_count > 0 {
            tight += 2.0 ;
        }
        if fitting_bins_count == 1 && next_item_size > 0 && next_item_size > post_residual {
            tight -= 2.5 ;
        }
        // opening a fresh bin is cheaper when fitting bins leave only slivers
        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if (avg_fit as u32) < item_size * 2 && progress < 0.85 {
                tight -= 1.0 ;
            }
        }
        // mid-stream: fresh bin guarantees a home for the next item
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && fitting_bins_count > 0 && progress < 0.7 {
            tight -= 2.0 ;
        }
        // sharpen sliver discrimination
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_after = mean_residual / (open_bins_count.max(1) as f64) ;
            if (best_after as u32) >= next_item_size {
                tight += 1.5 ;
            } else if progress > 0.75 {
                tight += 1.0 ;
            }
        }
        // late-stream conservation — near the end, opening a new bin is almost
        // never recoverable; push harder toward existing fits
        if progress > 0.8 && fitting_bins_count > 0 {
            tight += 2.5 * progress ;
        }
        // early-stream exploration — keep residual distribution wide early
        if progress < 0.1 && fitting_bins_count > 2 {
            tight -= 0.5 ;
        }
        // if only fitting bins would leave dead slivers below smallest item,
        // a fresh bin is genuinely better (dampened to avoid bin blowup)
        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if avg_fit < next_item_size as f64 + 1.0 && progress < 0.5 {
                tight -= 1.0 ;
            }
        }
        // if every fitting bin would leave a sliver smaller than the
        // smallest plausible item after taking this item, opening fresh is
        // strictly better; detect via mean residual proximity to item size
        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if (avg_fit as u32) >= item_size && (avg_fit as u32) < item_size + 3 && progress < 0.6 {
                tight -= 1.5 ;
            }
        }
        // NEW: when the current item exactly consumes a fitting bin's residual,
        // never open a fresh bin — that is a guaranteed zero-waste placement
        if fitting_bins_count > 0 && next_item_size > 0 {
            for _ in 0..0 {}
            if post_residual == 0 {
                tight += 4.0 ;
            }
        }
        score = norm_pr * 20.0 + tight ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // A gap is "dead" if it is smaller than the smallest plausible item (assume ~10,
    // scaled down slightly for late stream phases where small items are less likely).
    let min_item = if total_items > 0 { 10.0 } else { 10.0 };
    let phase = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dead_threshold = min_item * (1.0 - 0.3 * phase);

    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        // Heavy penalty proportional to how close we are to a full bin
        // (wasting space while looking almost full).
        score += 60.0 * (1.0 - post_residual as f64 / dead_threshold);
    }

    // Reward perfect / near-perfect fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if (post_residual as f64) < 0.05 * bin_capacity as f64 {
        score -= 30.0;
    }

    // Reward leaving room for the lookahead item if it can fit in the post gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        // Creating a gap that the next item cannot use: extra dead-space penalty.
        score += 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> penalize spreading, favor tight packing.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., tighter bins) so large residual bins stay available for big items.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 0.5 * (mean_residual - resid);
    } else {
        score += 0.3 * (resid - mean_residual);
    }

    // New-bin candidate handling: an empty bin is a fallback; only attractive when
    // no open bin offers a decent fit (post_residual small relative to capacity)
    // or when item is large and would leave a bad gap elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // But if the item is large, placing it in a fresh bin is natural.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // If many bins are already open, discourage more.
        score += 1.5 * open_bins_count as f64;
        // Late in the stream, opening bins is less costly (fewer future chances to fill).
        score -= 10.0 * phase;
    }

    score
}

