            if (after as f64) >= mean_residual / (open_bins_count.max(1) as f64) * 0.5 && after >= item_size / 2 {
                score -= 2.0 ;
            }
        }
        // exact-fit lookahead chain: residual left equals a plausible small item
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if after > 0 && after <= item_size && after <= next_item_size {
                score -= 4.0 ;
            }
        }
        // penalize awkward slivers just above next item, scaled by alternatives
        if post_residual > next_item_size && post_residual < next_item_size + 4 && fitting_bins_count > 1 {
            score += 3.0 * (1.0 - norm_pr) ;
        }
        // combined lookahead — if this bin's residual after taking the item
        // plus the fleet's average slack can host the next item, prefer it mildly
        if post_residual >= item_size {
            let slack = mean_residual / (open_bins_count.max(1) as f64) ;
            if (post_residual - item_size) as f64 + slack >= next_item_size as f64 {
                score -= 1.0 ;
            }
        }
        // exact-fit chain reward — post_residual exactly equals next item,
        // leaving zero waste; amplify with scarcity of alternatives
        if post_residual == next_item_size {
            score -= 2.0 + 1.0 / (fitting_bins_count.max(1) as f64) ;
        }
        // penalize large post-residuals that cannot host the next item
        // (waste that will persist), stronger when fleet slack is low
        if post_residual > 0 && post_residual < next_item_size {
            let fleet_tight = (mean_residual / cap).min(1.0) ;
            score += 2.0 * (1.0 - fleet_tight) * norm_pr ;
        }
        // MUTATION: waste-ratio coupling — bins whose post-residual fraction
        // exceeds the item's fraction waste disproportionate space; scale the
        // penalty by how much of the bin the item actually consumes
        let item_frac = item_size as f64 / cap ;
        if item_frac < 0.4 && norm_pr > item_frac * 2.0 {
            score += (norm_pr - item_frac * 2.0) * 14.0 ;
        }
        // MUTATION: pair-fill lookahead — if item + next fills this bin nearly
        // exactly, strongly prefer it (compaction of two items into one bin)
        let pair_fill = (item_size + next_item_size) as f64 / cap ;
        if pair_fill >= 0.97 && pair_fill <= 1.0 {
            score -= 5.0 ;
        }
    }

    if post_residual > 0 && post_residual < item_size.max(next_item_size) {
        score += 12.0 * (1.0 - norm_pr) ;
    }
    if post_residual > 0 && norm_pr < 0.02 {
        score -= 9.0 ;
    }

    if bin_residual == bin_capacity {
        let mut tight = 6.0 ;
        if next_item_size > 0 && next_item_size <= post_residual {
            tight = 0.0 ;
        }
        if fitting_bins_count == 0 {
            tight -= 4.0 ;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            tight += 3.0 ;
        }
        if fitting_bins_count > 0 {
            tight += 2.0 ;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let sliver = fitting_bins_count as f64 ;
            tight -= 1.5 * (sliver.recip()) ;
        }
        if norm_pr < 0.05 {
            tight -= 1.0 ;
        }
        if mean_residual / cap < 0.03 && fitting_bins_count > 0 {
            tight -= 1.5 ;
        }
        let progress = step_index as f64 / (total_items.max(1) as f64) ;
        if progress > 0.9 && fitting_bins_count > 0 {
            tight += 2.0 ;
        }
        if fitting_bins_count == 1 && next_item_size > 0 && next_item_size > post_residual {
            tight -= 2.5 ;
        }
        // opening a fresh bin is cheaper when fitting bins leave only slivers
        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if (avg_fit as u32) < item_size * 2 && progress < 0.85 {
                tight -= 1.0 ;
            }
        }
        // mid-stream: fresh bin guarantees a home for the next item
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && fitting_bins_count > 0 && progress < 0.7 {
            tight -= 2.0 ;
        }
        // sharpen sliver discrimination
        if fitting_bins_count > 0 && next_item_size > 0 {
            let best_after = mean_residual / (open_bins_count.max(1) as f64) ;
            if (best_after as u32) >= next_item_size {
                tight += 1.5 ;
            } else if progress > 0.75 {
                tight += 1.0 ;
            }
        }
        // late-stream conservation — near the end, opening a new bin is almost
        // never recoverable; push harder toward existing fits
        if progress > 0.8 && fitting_bins_count > 0 {
            tight += 2.5 * progress ;
        }
        // early-stream exploration — keep residual distribution wide early
        if progress < 0.1 && fitting_bins_count > 2 {
            tight -= 0.5 ;
        }
        // if only fitting bins would leave dead slivers below smallest item,
        // a fresh bin is genuinely better (dampened to avoid bin blowup)
        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if avg_fit < next_item_size as f64 + 1.0 && progress < 0.5 {
                tight -= 1.0 ;
            }
        }
        // if every fitting bin would leave a sliver smaller than the
        // smallest plausible item after taking this item, opening fresh is
        // strictly better; detect via mean residual proximity to item size
        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if (avg_fit as u32) >= item_size && (avg_fit as u32) < item_size + 3 && progress < 0.6 {
                tight -= 1.5 ;
            }
        }
        // MUTATION: if item + next item could jointly fill a fresh bin nearly
        // exactly, opening fresh is a strong compaction win
        let pair_fill = (item_size + next_item_size) as f64 / cap ;
        if fitting_bins_count > 0 && pair_fill >= 0.95 && pair_fill <= 1.0 && progress < 0.8 {
            tight -= 2.5 ;
        }
        score = norm_pr * 20.0 + tight ;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
