}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional dead space: waste relative to capacity
    score += 0.7 * (post_residual as f64 / bin_capacity as f64).powi(3) * 100.0;

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else {
            score += 6.0 + 0.10 * (next_item_size - post_residual) as f64;
        }
        // Perfect chain fit bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: minimize leftover aggressively
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 3 {
        score += 1.5 * (fitting_bins_count as f64 - 3.0);
    }

    // Tight fit reward (small post-residual relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness * tightness;

    // Global residual pressure: prefer bins below mean residual (consolidate)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Time horizon: early on, allow new bins; late, squeeze into existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 15.0 + 40.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // Open new bin if no open bin has enough for next item too
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Slight bonus for using existing bins late in the stream
        score -= 8.0 * progress;
    }

    // Prefer filling large-residual bins when many bins are open
    score += 0.03 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

