    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual class
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 8.0 + (slack as f64).min(10.0);
            if slack % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; leftover must stand alone
            score += 4.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer filling bins when many bins are open (bin consolidation)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 + progress) * 5.0;

    // Pull toward mean residual: avoid creating outliers
    score += 0.3 * (post - mean_residual).abs();

    // New-bin candidate: keep it neutral-to-slightly-tempting only when current bin is poor
    if bin_residual == bin_capacity {
        score += 12.0 - progress * 5.0;
        if class <= 2 {
            score -= 20.0; // opening a fresh bin beats tiny leftover classes
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let pr = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
