        // space is consumed vs wasted by this placement; bins leaving very large
        // unfillable remainders (relative to fleet slack) are deprioritized
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            let waste_frac = after as f64 / cap ;
