        // capacity and the fleet's mean residual would leave a worse waste ratio
        if fitting_bins_count > 0 && progress < 0.4 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            let fit_waste = (avg_fit - item_size as f64).max(0.0) / cap ;
            if item_size as f64 > cap * 0.4 && fit_waste > 0.15 {
                tight -= 1.8 ;
            }
        }
        // NEW: endgame — when nearly done, never open a bin unless nothing fits
        if progress > 0.95 && fitting_bins_count > 0 {
            tight += 4.0 ;
        }
        score = norm_pr * 20.0 + tight ;
    }

    score
}

