    if post_residual >= 1 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 25.0;
    } else if post_residual > 10 && post_residual < 20 {
        // mild penalty for mid-range awkward gaps
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Reward tight fits (small waste relative to item).
    let tightness = item_size as f64 / (bin_residual as f64 + 1.0);
    score -= tightness * 30.0;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: prefer reusing bins when many are open,
    // but relax pressure when this is the last fitting bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (2.0 + 3.0 * progress);
    if fitting_bins_count <= 1 {
        score -= pressure * 0.5;
    } else {
        score += pressure * 0.3;
    }

    // Dead-space penalty scaled by mean residual of the fleet:
    // if mean residual is already large, avoid adding to the pile of unusable space.
    if post_residual > 0 && post_residual < next_item_size.max(1) as u32 {
        score += 15.0; // gap can't fit the known next item
    }
    if (mean_residual - post_residual as f64).abs() < 5.0 {
        score -= 5.0; // keep residuals homogeneous for future packing
    }

    // New-bin candidate: empty bin has residual == capacity; discourage unless
    // no open bin fits well (handled by fitting_bins_count logic above) and
    // the item is large enough to justify fresh space.
    if bin_residual == bin_capacity {
        let base = 20.0 + 0.5 * open_bins_count as f64;
        score += base;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: opening is fine
        }
    }

    score
}

