        // almost never recoverable, so push harder toward existing fits
        if progress > 0.9 && fitting_bins_count > 0 {
            tight += 3.0 * progress ;
        }
        // NEW: if the fleet average residual already covers the next item, a
        // fresh bin is wasteful
        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count . max (1) as f64) ;
            if avg_fit >= next_item_size as f64 * 1.2 && progress < 0.6 {
                tight += 1.2 ;
            }
        }
        score = norm_pr * 20.0 + tight ;
    }

    score
}

