        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if (avg_fit as u32) >= item_size && (avg_fit as u32) < item_size + 3 && progress < 0.6 {
                tight -= 1.5 ;
            }
        }
        // borrowed from best: large items early with big fit waste -> open fresh
        if fitting_bins_count > 0 && progress < 0.4 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            let fit_waste = (avg_fit - item_size as f64).max(0.0) / cap ;
            if item_size as f64 > cap * 0.4 && fit_waste > 0.15 {
                tight -= 1.8 ;
            }
        }
        // borrowed from best: endgame lock — never open fresh at the very end
        if progress > 0.95 && fitting_bins_count > 0 {
            tight += 4.0 ;
        }
        // NEW: mid-stream, if the single best fitting bin would strand more
        // waste than the fleet's average slack, prefer a fresh bin mildly
        if fitting_bins_count == 1 && next_item_size > 0 && progress < 0.6 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64) ;
            if (post_residual as f64) > avg_fit * 1.6 && post_residual > item_size {
                tight -= 1.2 ;
            }
        }
        score = norm_pr * 20.0 + tight ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = norm_pr * norm_pr * 30.0 + norm_pr * 20.0;

    // Strong reward for near-perfect fill.
    if post_residual == 0 {
        score -= 1000.0;
    } else if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 800.0;
            if fitting_bins_count > 1 {
                score -= 6.0;
            }
        } else {
            // One-sided gap: only penalize overshoot, not undershoot.
            let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64 / cap;
            score += gap * gap * 10.0;
        }
        // Joint lookahead: post-residual can host the next item.
        if post_residual >= next_item_size && bin_residual >= item_size {
            let joint = (post_residual - next_item_size) as f64 / cap;
            score -= (1.0 - joint) * 7.0;
        }
        // Two-step lookahead: residual left after hosting next item is dead
        // if smaller than the current item; penalize.
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after > 0 && after < item_size {
                score += 3.0 * (1.0 - norm_pr);
            }
        }
        // Exact-fit lookahead chain: after hosting next item, the leftover
        // exactly matches a plausible small item (<= current item size).
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after > 0 && after <= item_size && after <= next_item_size {
                score -= 4.0;
            }
        }
        // Penalize near-miss slivers for next item when alternatives exist.
        if post_residual >= next_item_size && post_residual < next_item_size * 2 && fitting_bins_count > 1 {
            score += 2.5 * norm_pr;
        }
        // Next item won't fit post-residual: penalize wasted space.
        if next_item_size as f64 > pr && norm_pr > 0.15 {
            score += norm_pr * 6.0;
        }
        if post_residual < next_item_size && post_residual > 0 {
            // Undershoot sliver: worse if bin is nearly full (small norm_pr).
            score += 5.5 * (1.0 - norm_pr);
            if post_residual < item_size as f64 * 0.5 {
                score += 8.0 * norm_pr;
            }
        }
        // Refined dead-end metric: residual left after next item, weighted
        // by fleet slack scarcity.
        if post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64 / cap;
            let fleet_slack = (mean_residual / cap).min(1.0);
            if after > 0.0 {
                score += (1.0 - after) * (1.5 + 2.0 * (1.0 - fleet_slack));
            }
            // Waste relative to fleet slack: leftover much larger than the
            // typical slack elsewhere is a sign of poor consolidation.
            let fleet_slack_pos = (mean_residual / cap).max(0.01);
            if after > fleet_slack_pos * 1.8 {
                score += (after - fleet_slack_pos) * 9.0;
            }
            // Divisibility bonus: leftover nearly a multiple of next item.
            if after > 0 {
                let k = ((post_residual - next_item_size) as f64 / next_item_size as f64).floor();
                let rem = (post_residual - next_item_size) as f64 - k * next_item_size as f64;
                if rem < 2.0 {
                    score -= 2.0 * (1.0 - norm_pr);
                }
            }
        }
        // Reward bins whose post-residual still covers average upcoming demand.
        if post_residual >= next_item_size {
            let avg_next = mean_residual / (open_bins_count.max(1) as f64);
            if next_item_size as f64 <= avg_next * 1.5 {
                score -= 1.2 * norm_pr;
            }
        }
        // Penalize awkward just-above-next-item residuals creating slivers.
        if post_residual > next_item_size && post_residual < next_item_size + 4 && fitting_bins_count > 1 {
            score += 3.0 * (1.0 - norm_pr);
        }
    }

    // Penalize creating small unusable dead space.
    if post_residual > 0 && post_residual < item_size.max(next_item_size) {
        score += 12.0 * (1.0 - norm_pr);
    }
    // Reward near-perfect residuals that aren't zero.
    if post_residual > 0 && norm_pr < 0.02 {
        score -= 9.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0 * (1.0 - norm_pr);
    }

    // New-bin candidate logic: adaptive tightness based on lookahead fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut tight = 6.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            tight = 0.0;
        }
        if fitting_bins_count == 0 {
            tight -= 4.0;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            tight += 3.0;
        }
        if fitting_bins_count > 0 {
            tight += 2.0;
            if next_item_size > 0 {
                tight -= 1.5 / (fitting_bins_count as f64);
            }
        }
        if norm_pr < 0.05 {
            tight -= 1.0;
        }
        if mean_residual / cap < 0.03 && fitting_bins_count > 0 {
            tight -= 1.5;
        }
        if progress > 0.9 && fitting_bins_count > 0 {
            tight += 2.0;
        } else if progress < 0.2 {
            tight += 2.0;
        }
        if fitting_bins_count == 1 && next_item_size > 0 && next_item_size > post_residual {
            tight -= 2.5;
        }
        // Mid-stream: fleet mean residual can't host next item -> fresh bin
        // guarantees a home for it; dampen new-bin penalty.
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && fitting_bins_count > 0 && progress < 0.7 {
            tight -= 2.0;
        }
        // Late-stream conservation: opening a new bin is rarely recoverable.
        if progress > 0.8 && fitting_bins_count > 0 {
            tight += 2.5 * progress;
        }
        if progress > 0.95 && fitting_bins_count > 0 {
            tight += 4.0;
        }
        // Sharpen sliver discrimination: if fleet mean residual can still
        // host the next item, prefer existing bins.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let avg_fit = mean_residual / (open_bins_count.max(1) as f64);
            if avg_fit >= next_item_size as f64 {
                tight += 1.5;
            } else if progress > 0.75 {
                tight += 1.0;
            }
            // If average slack barely fits the next item early on, open a
            // fresh bin to preserve clean residuals for future items.
            if avg_fit < next_item_size as f64 + 1.0 && progress < 0.5 {
                tight -= 1.0;
            }
            // Large items with poor fleet fit: fresh bin avoids fragmentation.
            let fit_waste = (avg_fit - item_size as f64).max(0.0) / cap;
            if item_size as f64 > cap * 0.4 && fit_waste > 0.15 && progress < 0.4 {
                tight -= 1.8;
            }
            if (avg_fit as u32) < item_size * 2 && progress < 0.85 {
                tight -= 1.0;
            }
        }
        score = norm_pr * 20.0 + tight;
    }

    // Mild tie-breaking: prefer bins already below mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Lookahead: stranded tight-bin avoidance.
    if next_item_size > post_residual && bin_residual < item_size * 2 {
        score += 8.0 * norm_pr;
    }

    score
}

