pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if (next_item_size as u32) > post_residual {
            score += 12.0 * (next_item_size as f64 - post_residual as f64).min(30.0);
        } else if post_residual >= next_item_size as u32 {
            score -= 4.0; // next item can chain into this bin
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Prefer bins whose residual deviates below the mean (consolidate small leftovers).
    let deviation = bin_residual as f64 - mean_residual;
    score += 0.15 * deviation;

    // Early in the stream, be more willing to open new bins (keep flexibility);
    // late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins more as stream progresses,
        // and when many bins are already open.
        let mut new_bin_penalty = 20.0 + 30.0 * progress + 0.5 * open_bins_count as f64;
        // But if the item is large and few bins fit it, opening a bin is attractive.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: mild reward that grows late in the stream.
        score -= 3.0 * progress;
    }

    // Slight preference for bins with moderate residual (avoid fragmenting nearly-full bins
    // with tiny items when a better use may come later).
    if post_residual > 0 && post_residual < 5 {
        score += 6.0; // nearly perfect fit, but tiny residue is fine; small penalty for waste
    }

    // Cap extreme negative scores so ordering stays meaningful.
    if score < -60.0 { score = -60.0; }

    score
}

