pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity / integer division thresholds
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let q = post_residual / (bin_capacity / 4); // quarter-class of leftover space

    // Reward placements that leave a residual in a "reusable" harmonic class.
    // Residuals in [1,9] are near-dead; residuals divisible by 10 pair well with small items.
    let dead_zone = (post_residual > 0 && post_residual < 10) as f64;
    let harmonic_good = (post_residual % 10 == 0 && post_residual > 0) as f64;
    score += dead_zone * 25.0;
    score -= harmonic_good * 8.0;

    // Perfect fit is best
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize wasting a large residual on a small item (bad fill ratio)
    let fill = item_size as f64 / bin_residual as f64;
    if fill < 0.35 {
        score += (0.35 - fill) * 40.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // post_residual too small for next item: penalize by dead-space amount
            score += (next_item_size as f64 - post).min(20.0) * 0.8;
        }
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is terrible
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowded = (open_bins_count as f64).max(1.0);
        let avg_crowd = mean_residual / cap;
        // base penalty so new bins aren't opened frivolously
        score += 60.0;
        // more open bins with low mean residual -> discourage new bin
        score += avg_crowd * 30.0 + crowded * 2.0;
        // late in stream, prefer closing out bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
        // if next item is large, a fresh bin is valuable
        if next_item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Modulo-3 harmonic nudge on post_residual (avoid awkward classes like 4,7 mod 10)
    let awkward = ((post_residual % 10) >= 4 && (post_residual % 10) <= 7 && post_residual >= 10) as f64;
    score += awkward * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Moderate gaps (10..=item_size range) are usable; slight reward scaled by gap size.
    if post_residual >= 10 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: penalize leaving a gap that traps the next item.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: prefer placing into existing bins when many are open.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: make empty bins less attractive unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Slight tie-break: prefer tighter existing bins.
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: leave nothing behind.
    if post_residual == 0 {
