        }
    }

    // Mild penalty for leaving tiny unusable slivers (1..=5).
    if post_residual > 0 && post_residual <= 5 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small post_residual relative to item).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(6);

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 / (1.0 + slack);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty, stronger if this creates a near-empty leftover.
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in stream, or few open bins, favor consolidation instead.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        if open_bins_count > 0 && item_size <= 50 {
            score += 15.0;
        }
        // Opening a new bin is fine for big items that leave a useful residual.
        if item_size >= 70 {
            score -= 18.0;
        }
    }

    // Prefer bins deviating from the mean residual (keep residuals diverse/complementary).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // Prefer filling fuller bins (best-fit flavor) as stream progresses.
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 8.0 * fill * (0.5 + 0.5 * step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post residual), with non-linear shaping
    let mut score = post;

    // Smooth non-linear coupling: waste penalty grows super-linearly with
    // normalized dead space, modulated by stream progress.
    let dead_space = norm_post * norm_post;
    score += 40.0 * dead_space * (0.5 + 0.5 * progress) * cap;

    // Interaction of post_residual with progress: late in the stream,
    // tolerate less residual waste (favor fuller bins even more).
    score += 20.0 * norm_post * progress * cap;

    // Lookahead coupling: reward bins whose post residual fits next item well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_gap = (post_residual - next_item_size) as f64 / cap;
        score -= 30.0 * (1.0 - fit_gap) * (1.0 - progress);
    } else if next_item_size > post_residual {
        // Dead space relative to next item penalized smoothly
        let gap = (next_item_size - post_residual) as f64 / cap;
        score += 15.0 * gap * gap * cap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else {
        // Slight preference for bins among many candidates that still fit tightly
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean-residual coupling: prefer bins close to the mean residual
    // (balanced packing), with smooth quadratic term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev * cap;

    // Mild penalty for spreading across many open bins early on
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to capacity (smooth in item_size).
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        score += 25.0 * (1.0 - size_frac) * (1.0 + progress);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
