        if pr > 80 {
            score -= 10.0; // large residual still very usable
        }
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Integer-division threshold classes on post_residual
    let pr_class = pr / 10; // classes 0..10
    score += (10 - pr_class.min(10)) as f64 * 1.5;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 12.0; // near-perfect two-item packing
            } else {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; penalize small residuals more
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    } else {
        // Last item: prefer tightest fit overall
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 1.0;
    }

    // Prefer bins tighter than the mean (best-fit flavor), scaled by stream progress
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let deviation = mean_residual - bin_residual as f64;
    score -= deviation * (0.5 + 0.5 * progress);

    // New-bin candidate: keep it unattractive unless the fit into open bins is bad
    if bin_residual == bin_capacity {
        // base cost of opening a bin; large residual would otherwise win
        score += 45.0 + (open_bins_count as f64) * 0.5;
        // late in the stream, opening fresh bins is less costly
        score -= progress * 20.0;
        // if the item is huge relative to typical residual, new bin is fine
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Any leftover gap that cannot fit even the smallest plausible item is dead space.
    // Penalize small unusable gaps super-linearly; large gaps remain usable.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            // tiny unusable sliver: strongly penalize
            score += (10.0 - pr) * 8.0;
        } else if pr < 20.0 {
            // awkward gap: only fits very small items
            score += (20.0 - pr) * 3.0;
        } else {
            // usable gap: mild reward proportional to remaining flexibility
            score -= (pr - 20.0).min(40.0) * 0.5;
        }
    } else {
        // perfect fill: big reward
        score -= 50.0;
    }

    // --- Tightness reward: fraction of bin consumed ---
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 30.0;

    // --- Open-bin pressure: discourage opening new bins when many are open ---
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 40.0 + open_bins_count as f64 * 2.0;
        // early in stream, new bins are cheap; later they are expensive
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
    }

    // --- Last-chance bonus: if this is the only fitting bin, prefer using it ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // --- Lookahead: if next item fits exactly into post_residual, big reward ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score -= 30.0; // next item will perfectly consume leftover
            } else {
                score -= 8.0;
            }
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            // leftover too small for the known next item: dead space confirmed
            score += 15.0;
        }
    }

    // --- Mean residual coupling: prefer bins whose residual is below average
    // (concentrate packing into tighter bins, keep looser bins flexible) ---
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: ideal placement leaves a residual exactly
    // matching the next item size (perfect chain), or zero (perfect fill).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward exact match strongly, penalize mismatch proportionally.
        score += gap * 1.5;

        // Perfect chain bonus: post_residual == next_item_size means next
        // item closes this bin completely.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Dead-space penalty: residual too small for next item and below
        // typical minimum item size -> likely wasted space.
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 20.0;
        }
    } else {
        // Last item: pure tightest-fit behavior.
        score -= 10.0;
    }

    // Reward closing bins tightly (small post_residual relative to mean residual).
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current residuals are badly
    // fragmented (mean residual low relative to item) or no open bin fits well.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize opening new bins mildly by default.
        score += 30.0;
        // But if open bins are nearly full (low mean residual), a new bin
        // becomes reasonable: reduce the penalty.
        score -= (1.0 - fragmentation) * 20.0;
        // Perfect lookahead fit in a fresh bin (item + next item = capacity).
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 40.0;
        }
    }

    // Slight progression bias: later in the stream, favor consolidating
    // (tighter fits matter more as remaining items dwindle).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Prefer bins among many fitting candidates that leave more usable space.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual already does this), sharpen it.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Lookahead: strongly reward bins where the NEXT item also fits the post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_tightness = next_item_size as f64 / post_residual as f64;
        score -= 12.0 + 18.0 * chain_tightness;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        // Dead space too small for next item: penalize
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless item is huge
    // or the fit elsewhere is terrible.
    if bin_residual == bin_capacity {
        // Cost of a fresh bin: base penalty that shrinks as stream progresses
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 45.0 - 15.0 * progress;
        // If many bins are open and residuals are fragmented, a new bin is more acceptable
        new_bin_cost -= 3.0 * (open_bins_count as f64).min(10.0);
        // Huge items nearly fill a bin alone: new bin is fine
        if item_size as f64 / bin_capacity as f64 > 0.9 {
            new_bin_cost -= 60.0;
        }
        score += new_bin_cost.max(0.0);
    } else {
        // Reward filling existing bins proportionally to how much of residual is used
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Global state coupling: if mean residual is high, avoid leaving this bin worse than average
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);

    // Small dead-space cliff: residuals below 10 are nearly useless
    if post_residual < 10 {
        score += 0.5 * (10 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post-residual, mildly normalized.
    let mut score = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, tight fits matter more (dead space is costlier).
    let tightness = 1.0 - (pr / cap);
    score -= (progress * tightness * tightness) * 6.0;

    // Polynomial penalty on small post-residuals that waste capacity,
    // weighted by how much slack the fleet already has.
    let fleet_slack = (mean_residual / cap).clamp(0.0, 1.0);
    score += (1.0 - progress) * (pr / cap).powi(3) * 4.0 * fleet_slack;

    // Perfect-fit reward: quadratic in fill ratio, stronger late.
    let fill = item_size as f64 / cap;
    score -= fill * fill * (0.5 + progress) * 2.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 3.0 + progress * 2.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = (pr - nxt) / cap;
            score -= (1.0 - gap * gap) * (2.0 + progress * 3.0);
        } else {
            score += (nxt - pr) / cap * 0.5;
        }
    }

    // New-bin candidate: penalize mildly so it is chosen only when
    // open bins are poor fits; penalty grows with fleet slack.
    if bin_residual == bin_capacity {
        score += 1.5 + fleet_slack * 2.0 - progress * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which "denomination" slots remain
    let leftover_class = (post_residual / 10) as f64;
    let exact_fit = post_residual == 0;

    // Reward perfect fits strongly
    if exact_fit {
        score -= 60.0;
    } else {
        // Penalize leftovers that fall into "dead zones" (small unusable slivers)
        if post_residual < 10 {
            score += 25.0;
        } else if post_residual <= 20 {
            score += 8.0;
        }

        // Harmonic coupling: leftover divisible by common item denominations
        // (10, 20, 25, 50 classes) is more likely to be filled later.
        if post_residual % 50 == 0 {
            score -= 18.0;
        } else if post_residual % 25 == 0 {
            score -= 10.0;
        } else if post_residual % 10 == 0 {
            score -= 6.0;
        } else {
            score += 4.0; // awkward remainder class
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let next_leftover = post_residual - next_item_size;
            // prefer chains that keep usable residues
            if next_leftover % 10 == 0 {
                score -= 12.0;
            }
            if next_leftover < 10 {
                score += 10.0; // creates dead sliver after next item
            }
        } else {
            // next item won't fit here: mild penalty for blocking the chain
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when current item is large relative to capacity or many open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        // Opening a new bin is good for big items late in stream or when
        // open bins are already crowded (mean residual small).
        score -= 20.0 * item_frac * (0.5 + progress);
        if mean_residual < 15.0 && open_bins_count > 2 {
            score -= 15.0;
        }
        // discourage hoarding bins early
        score += open_bins_count as f64 * 1.5;
    }

    // Tightness bonus: filling a bin closer to capacity is better
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item (1..=10 range implies anything < 10 is pure dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Harsh penalty on moderately small residuals that rarely get used.
    if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (1.0 - tightness);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item can use the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: neutral baseline, penalize opening bins early or when
    // mean residual across open bins is already large.
    if bin_residual == bin_capacity {
        score += 30.0;
        score += 2.0 * mean_residual;
        score -= 20.0 * progress;
    }

    // Prefer bins whose residual deviates from mean in a usable (large) way.
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward an exact match between
    // post_residual and the next item's size (perfect two-item fill).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Exact match gets a big bonus; near matches scale down smoothly.
        if diff == 0.0 {
            score -= 60.0;
        } else if diff <= 10.0 {
            score -= 40.0 * (1.0 - diff / 10.0);
        } else {
            score += diff * 0.3;
        }

        // If the next item cannot fit into the post-residual, penalize leaving
        // behind dead space that is smaller than the next item.
        if post_residual < next_item_size {
            let waste = next_item_size as f64 - post_residual as f64;
            score += waste * 0.8;
        }
    } else {
        // Last item: prefer tightest fit, minimal residual.
        score += 5.0;
    }

    // Penalize post-residuals in the "dead zone": too small for any realistic
    // future item (items >= 1, but small slivers below 10 are nearly unusable).
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.5;
    }

    // Contextual adjustment: if this is the only bin that can fit the item,
    // heavily reward using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Relative-to-mean coupling: bins with residual far below the mean are
    // already tight; placing here consolidates waste. Reward that.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.4 * (res - mean_residual);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer a new bin when no open bin offers a good (near-exact) fit:
        // i.e., when the best-case post residual is large relative to capacity.
        // Penalize new bins mildly so they only win when open bins are bad.
        score += 12.0;
        // But if the item fits almost perfectly in a fresh bin (small item),
        // a new bin is fine; reduce the penalty proportionally to item size.
        score -= item_size as f64 * 0.05;
        // Late in the stream, avoid proliferating bins unnecessarily.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 8.0;
    }

    // Mild bonus for using bins that are already quite full (small residual).
    score += 0.15 * (bin_capacity - bin_residual) as f64;

    // Slight preference to keep the number of open bins low early on.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let pr = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let norm_pr = pr / cap ;
    let mut score = norm_pr * norm_pr * 30.0 + norm_pr * 20.0 ;

    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64 / cap ;
        score += gap * gap * 10.0 ;
        if next_item_size == post_residual {
            score -= 50.0 ;
        } else if next_item_size as f64 > post_residual as f64 && post_residual < item_size as f64 * 0.5 {
            score += 8.0 * norm_pr ;
        }
        if post_residual >= next_item_size && bin_residual >= item_size {
            let joint = (post_residual - next_item_size) as f64 / cap ;
            score -= (1.0 - joint) * 7.0 ;
        }
        if next_item_size as f64 > pr && norm_pr > 0.15 {
            score += norm_pr * 6.0 ;
        }
        if post_residual < next_item_size && post_residual > 0 {
            score += 5.5 * (1.0 - norm_pr) ;
        }
        if post_residual >= next_item_size && post_residual < next_item_size * 2 && fitting_bins_count > 1 {
            score += 2.5 * norm_pr ;
        }
        if next_item_size == post_residual && fitting_bins_count > 1 {
            score -= 6.0 ;
        }
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if after > 0 && after < item_size {
                score += 3.0 * (1.0 - norm_pr) ;
            }
        }
        // dead-end metric: residual left after hosting the next item is only
        // useful if it can host at least a small item; weight by fleet slack
        if post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64 / cap ;
            let usable = if after > 0.0 { 1.0 } else { 0.0 } ;
            let fleet_slack = (mean_residual / cap).min(1.0) ;
            score += (1.0 - after) * usable * (1.5 + 2.0 * (1.0 - fleet_slack)) ;
        }
        // reward bins whose post-residual still covers average upcoming demand
        if post_residual >= next_item_size {
            let avg_next = mean_residual / (open_bins_count.max(1) as f64) ;
            if next_item_size as f64 <= avg_next * 1.5 {
                score -= 1.2 * norm_pr ;
            }
        }
        // near-perfect-fill bonus — item exactly leaves a tiny unusable crumb
        if post_residual > 0 && post_residual < 4 {
            score -= 4.0 + 3.0 * (1.0 - norm_pr) ;
        }
        // two-step lookahead — post-residual can also hold approximated next demand
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if (after as f64) >= mean_residual / (open_bins_count.max(1) as f64) * 0.5 && after >= item_size / 2 {
                score -= 2.0 ;
            }
        }
        // exact-fit lookahead chain: residual left equals a plausible small item
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if after > 0 && after <= item_size && after <= next_item_size {
                score -= 4.0 ;
            }
        }
        // penalize awkward slivers just above next item, scaled by alternatives
        if post_residual > next_item_size && post_residual < next_item_size + 4 && fitting_bins_count > 1 {
            score += 3.0 * (1.0 - norm_pr) ;
        }
        // combined lookahead — if this bin's residual after taking the item
        // plus the fleet's average slack can host the next item, prefer it mildly
        if post_residual >= item_size {
            let slack = mean_residual / (open_bins_count.max(1) as f64) ;
            if (post_residual - item_size) as f64 + slack >= next_item_size as f64 {
                score -= 1.0 ;
            }
        }
        // exact-fit chain reward — post_residual exactly equals next item,
        // leaving zero waste; amplify with scarcity of alternatives
        if post_residual == next_item_size {
            score -= 2.0 + 1.0 / (fitting_bins_count.max(1) as f64) ;
        }
        // penalize large post-residuals that cannot host the next item
        // (waste that will persist), stronger when fleet slack is low
        if post_residual > 0 && post_residual < next_item_size {
            let fleet_tight = (mean_residual / cap).min(1.0) ;
            score += 2.0 * (1.0 - fleet_tight) * norm_pr ;
        }
        // gen42: cubic dead-space ramp on the after-residual — punish gaps that
        // no plausible future item (min of item/next scaled) can absorb
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            let dead = after as f64 / cap ;
            let floor = item_size.min(next_item_size) as f64 ;
            if after > 0 && dead > 0.010 && (after as f64) < floor * 2.5 {
                score += dead * dead * dead * 320.0 * (1.0 - norm_pr) ;
            }
        }
        // gen42: self-reusable residual — bin can host the item again after
        // taking the next one; keep such chains alive
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if after >= item_size && item_size > 0 && after >= next_item_size {
                score -= 2.4 * (1.0 - norm_pr) ;
            }
        }
        // gen42: residual that neither next item nor fleet average can use is stranded
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            let fleet_avg = mean_residual / (open_bins_count.max(1) as f64) ;
            if after > 0 && (after as f64) < fleet_avg * 0.5 && (after as f64) < next_item_size as f64 * 0.5 {
                score += 2.8 * (1.0 - norm_pr) ;
            }
        }
        // gen42: reward exact two-item packing chains (item + next fills bin fully)
        if item_size + next_item_size == post_residual && bin_residual == item_size + next_item_size {
            score -= 3.5 ;
        }
        // gen42: divisibility bonus — leftover is an exact multiple of next item
        if post_residual >= next_item_size && next_item_size > 0 {
            let after = post_residual - next_item_size ;
            if after > 0 && after % next_item_size.max(1) == 0 {
                score -= 3.0 * (1.0 - norm_pr) ;
            }
        }
        // gen42: residual that can still hold the current item again after next
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size ;
            if after >= item_size && item_size > 0 {
                score -= 2.2 * (1.0 - norm_pr) ;
            }
        }
    }

    if post_residual > 0 && post_residual < item_size.max(next_item_size) {
        score += 12.0 * (1.0 - norm_pr) ;
    }
    if post_residual > 0 && norm_pr < 0.02 {
        score -= 9.0 ;
    }

    if bin_residual == bin_capacity {
        let mut tight = 6.0 ;
        if next_item_size > 0 && next_item_size <= post_residual {
            tight = 0.0 ;
        }
        if fitting_bins_count == 0 {
            tight -= 4.0 ;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            tight += 3.0 ;
        }
        if fitting_bins_count > 0 {
            tight += 2.0 ;
