pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = r;

    // Squared/cubic residual terms: penalize large dead space super-linearly
    score += 0.012 * r * r / cap;
    score -= 0.00004 * r * r * r / cap;

    // Progress interaction: as stream advances, prefer tighter fits more strongly
