    score -= 30.0 * progress * tightness * tightness;
    score += 15.0 * progress * (r / cap) * (1.0 - r / cap);

    // Smooth lookahead coupling: reward residual that could fit next item
    if next_item_size > 0 {
        let gap = r - next_item_size as f64;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - gap / cap) * (0.5 + progress);
        } else {
            score += 0.05 * (-gap) * (1.0 + progress);
        }
    }

    // Last-chance bonus: smooth reward when few fitting bins
