    score += 0.02 * dev * dev / cap;

    // Mild penalty for proliferating open bins late in stream
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by modulo classes.
    // Residuals that are multiples of small "harmonic" units are more reusable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        60.0 // perfect fit: strongly reward
    } else if pr % 10 == 0 {
        18.0
    } else if pr % 5 == 0 {
        9.0
    } else if pr % 25 == 0 {
        12.0
    } else if pr % 20 == 0 {
        10.0
    } else {
        0.0
