    score -= harmonic_bonus;

    // Penalize small dead space that is too small for the smallest possible item (1..100 interface).
    // Dead space below the minimum item size is pure waste.
    if pr > 0 && pr < 10 {
        score += 25.0 + (10 - pr) as f64;
    }

    // Lookahead: reward if next item fits in the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
