pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect and near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would leave a worse gap, penalize slightly.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 && (post_residual - next_item_size) > 0 {
        score += 8.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 4.0 * (0.5 + progress);
    score -= pressure;

    // Prefer bins tighter than average (well-utilized bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: penalize mildly so it only wins when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 12.0 + (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fill this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits with modest slack: strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.25;
    }
    // Next item does NOT fit: penalize creating dead space that blocks lookahead.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Tight fill reward: small post residual is good, but zero-exact is best.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual < 10 {
        score += 10.0; // unusable sliver for typical items
    }

    // Compare residual against the mean of open bins: prefer bins that absorb
    // the item without inflating average fragmentation.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - pr) * 0.15;
    }

    // Last chance: only this bin can fit the item; strongly prefer it over
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperate = next_item_size > 0
            && post_residual < next_item_size
            && post_residual > 0;
        if desperate {
            score -= 30.0; // current bin would strand dead space; fresh bin better
        } else {
            score += 70.0; // keep using open bins when they fit reasonably
        }
    }

    // Early in the stream, slightly prefer opening bins to build flexibility.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity && progress < 0.2 {
            score -= 5.0;
        }
    }

    // Mild penalty for many open bins already (encourage consolidation later).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
