        score += 3.0;
    }

    // Last-chance bonus: only one bin fits; avoid opening a new bin if fit is decent.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into fuller bins.
    let open_pressure = (open_bins_count as f64) / ((total_items as f64).max(1.0)).sqrt();
    score -= open_pressure * (bin_residual as f64 / bin_capacity as f64) * 2.0;

